// Shared time-formatting helpers for worker clock times.
// Worker timestamps are stored/returned in Europe/Riga, so clock times are
// rendered in that timezone regardless of the viewer's browser timezone.

const RIGA_TIME_ZONE = 'Europe/Riga';

// "09:01" for an ISO string, "" for empty/invalid.
export const formatTime = (iso) => {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '';
  return new Intl.DateTimeFormat('en-GB', {
    timeZone: RIGA_TIME_ZONE,
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  }).format(d);
};

// 30 -> "30m", 95 -> "1h 35m"
export const formatBreakTime = (minutes) => {
  const total = Math.round(Number(minutes) || 0);
  const h = Math.floor(total / 60);
  const m = total % 60;
  return h > 0 ? `${h}h ${m}m` : `${m}m`;
};

// 7.5 -> "7.50h"; null/undefined/NaN -> "—"
export const formatHours = (hours) => {
  if (hours === null || hours === undefined || isNaN(Number(hours))) return '—';
  return `${Number(hours).toFixed(2)}h`;
};
